type AppState = {
    user: { name: string; loggedIn: boolean }
    theme: string
    notifications: number
}

function reducer(state: Readonly<AppState>, action: "LOGIN" | "LOGOUT" | "TOGGLE_THEME"): AppState {
    switch (action) {
        case "LOGIN":
            return { ...state, user: { ...state.user, loggedIn: true } }
        case "LOGOUT":
            return { ...state, user: { ...state.user, loggedIn: false }, notifications: 0 }
        case "TOGGLE_THEME":
            return { ...state, theme: state.theme === "light" ? "dark" : "light" }
    }
}

let state: AppState = { user: { name: "Ali", loggedIn: false }, theme: "light", notifications: 5 }

state = reducer(state, "LOGIN")
console.log(state.user)
state = reducer(state, "TOGGLE_THEME")
console.log("Tema:", state.theme)
state = reducer(state, "LOGOUT")
console.log(state)

