type Pizza = { size: "S" | "M" | "L"; cheese: boolean; toppings: string[] }

class PizzaBuilder {
    private parts: Partial<Pizza> = {}
    size(s: Pizza["size"]) { this.parts.size = s; return this }
    cheese(c = true) { this.parts.cheese = c; return this }
