const ROLES = ["admin", "editor", "viewer"] as const   // readonly ["admin", "editor", "viewer"]
type Role = (typeof ROLES)[number]                      // "admin" | "editor" | "viewer"

function isRole(value: string): value is Role {
    return (ROLES as readonly string[]).includes(value)
}

console.log(ROLES.length, isRole("editor"), isRole("guest"))
// ROLES.push("guest")   // Xato: 'push' does not exist on type 'readonly ["admin", "editor", "viewer"]'

type Editor = { text: string; size: number; bold: boolean }

const history: Partial<Editor>[] = []
let state: Editor = { text: "Salom", size: 14, bold: false }

function apply(changes: Partial<Editor>) {
    const previous: Partial<Editor> = {}
    for (const key of Object.keys(changes) as (keyof Editor)[]) {
        (previous as Record<string, unknown>)[key] = state[key]
    }
    history.push(previous)
    state = { ...state, ...changes }
}

function undo() {
    const previous = history.pop()
    if (previous) state = { ...state, ...previous }
}

apply({ size: 18 })
apply({ bold: true, text: "Salom, dunyo" })
console.log(state)
undo()
console.log(state)
undo()
console.log(state)

