function debounce<F extends (...args: any[]) => void>(fn: F, ms: number) {
    let t: ReturnType<typeof setTimeout> | undefined
    return (...args: Parameters<F>) => { clearTimeout(t); t = setTimeout(() => fn(...args), ms) }
}

const save = debounce((title: string, draft: boolean) => console.log("saqlandi:", title, draft), 20)
save("Qoralama 1", true)
save("Qoralama 2", false)

