function memoize<F extends (...a: any[]) => any>(fn: F) {
    const cache = new Map<string, ReturnType<F>>()
    return (...a: Parameters<F>): ReturnType<F> => {
        const k = JSON.stringify(a)
        if (!cache.has(k)) cache.set(k, fn(...a))
        return cache.get(k)!
    }
}
let calls = 0
const slowAdd = memoize((a: number, b: number) => { calls++; return a + b })
console.log(slowAdd(1, 2), slowAdd(1, 2), slowAdd(2, 1), "chaqiruvlar:", calls)

