type ObjectDescriptor<D, M> = {
    data?: D
    methods?: M & ThisType<D & M>   // methods ichida this: D & M
}

function makeObject<D, M>(desc: ObjectDescriptor<D, M>): D & M {
    const data: object = desc.data || {}
    const methods: object = desc.methods || {}
    return { ...data, ...methods } as D & M
}

const point = makeObject({
    data: { x: 0, y: 0 },
    methods: {
        moveBy(dx: number, dy: number) {
            this.x += dx   // this.x — data'dan, tipi number
            this.y += dy
        },
    },
})

point.x = 10
point.moveBy(5, 5)
console.log(point.x, point.y)

function throttle<F extends (...a: any[]) => void>(fn: F, ms: number) {
    let last = -Infinity
    return (now: number, ...a: Parameters<F>) => { if (now - last >= ms) { last = now; fn(...a) } }
}
const log = throttle((msg: string) => console.log("log:", msg), 100)
log(0, "a"); log(50, "b"); log(120, "c"); log(150, "d")

