type Resolved<T extends Record<string, Promise<unknown>>> = { [K in keyof T]: Awaited<T[K]> }

async function resolveAll<T extends Record<string, Promise<unknown>>>(tasks: T): Promise<Resolved<T>> {
    const entries = await Promise.all(
        Object.entries(tasks).map(async ([key, promise]) => [key, await promise] as const),
    )
    return Object.fromEntries(entries) as Resolved<T>
}

const data = await resolveAll({
    user: Promise.resolve({ id: 1, name: "Ali" }),
    orders: Promise.resolve([10, 20, 30]),
})

console.log(data.user.name, data.orders.length)   // tiplar avtomatik: { id; name } va number[]

