type Options<D, M> = {
    data: () => D
    methods: M & ThisType<D & M>
}

function defineComponent<D, M>(options: Options<D, M>): D & M {
    return Object.assign({}, options.data(), options.methods) as D & M
}

const cart = defineComponent({
    data: () => ({ items: [] as string[] }),
    methods: {
        add(name: string) { this.items.push(name) },
        summary() { return `${this.items.length} ta: ${this.items.join(", ")}` },
    },
})

cart.add("olma")
cart.add("nok")
console.log(cart.summary())

