type State = { items: { name: string; price: number }[]; user: string }

const selectors = {
    count: (s: State) => s.items.length,
    total: (s: State) => s.items.reduce((sum, i) => sum + i.price, 0),
    label: (s: State) => `${s.user}: ${s.items.length} ta`,
}

type Selected = { [K in keyof typeof selectors]: ReturnType<(typeof selectors)[K]> }
// { count: number; total: number; label: string }

function selectAll(state: State): Selected {
    return {
        count: selectors.count(state),
        total: selectors.total(state),
        label: selectors.label(state),
    }
}

console.log(selectAll({ user: "Ali", items: [{ name: "non", price: 4000 }, { name: "sut", price: 12000 }] }))

